parameters.jsCode:
// Fan-out satu item per slide. Node `Gemini gambar` memproses satu item per
// panggilan, jadi ini yang membuat carousel 5 slide menghasilkan 5 gambar;
// `Rakit slide` menggabungnya kembali jadi satu item.
const brief = $('Siapkan brief').first().json;
// Dibaca lewat nama node, bukan $input: node-node TMDB menyisip di antara `Gemini copy`
// dan node ini, jadi $input sudah bukan keluaran copy lagi.
const c = $('Gemini copy').first().json.output;

if (!c || !Array.isArray(c.slides) || !c.slides.length) {
  throw new Error(
    'Gemini copy tidak mengembalikan slides[]. Ini beda dari "model menolak": ' +
      `output yang diterima = ${JSON.stringify(c).slice(0, 300)}`
  );
}

// Rentang aman IG carousel adalah 2-10 item. Prompt meminta 5; potong di 10 kalau
// model kebablasan, dan gagal keras kalau cuma 1 supaya tidak diam-diam jadi post biasa.
const slides = c.slides.slice(0, 10);
if (slides.length < 2) {
  throw new Error(`Cuma ${slides.length} slide — IG carousel butuh minimal 2.`);
}

// Sufiks dikunci di kode, bukan di prompt: ini syarat teknis yang tidak boleh
// dinegosiasikan model. Semua teks hidup di HTML, nol di raster.
// Arah cahaya/warna datang dari model per artikel, bukan dipatok di sini. Dulu baris
// ini memaksa "muted desaturated palette, dark moody background" ke SEMUA artikel, dan
// itu yang bikin review film dan catatan teknis menghasilkan foto yang sama gelapnya.
//
// Yang tetap dikunci di kode cuma dua, karena keduanya syarat teknis yang tidak boleh
// dinegosiasikan model: nol teks di raster, dan ruang lapang di zona teks.
const RUANG = {
  'blok-bawah': 'Leave the lower third visually calm and uncluttered.',
  'pias-bawah': 'Keep the main subject in the upper half of the frame.',
  tengah: 'Leave the centre of the frame open and uncluttered.',
};
const mood = String(c.image_mood || '').trim();
const SUFIKS =
  `Photographic, shallow depth of field.${mood ? ` ${mood}.` : ''} ` +
  `${RUANG[c.layout] || RUANG['blok-bawah']} ` +
  'Absolutely no text, letters, numbers, watermarks, logos or user interface anywhere.';

/**
 * Kolam foto ASLI untuk artikel film.
 *
 * Model gambar menolak menggambar karakter berhak cipta dan wajah orang nyata, jadi
 * Spider-Man dan Sadie Sink tidak akan pernah keluar dari Gemini. Kalau artikelnya ulasan
 * film, fotonya diambil dari still resmi filmnya; artikel lain tetap digenerate.
 *
 * Diurutkan `vote_average` menurun lalu diambil SELANG, bukan lima teratas berurutan:
 * puluhan backdrop dari satu film hampir selalu memuat beberapa frame dari adegan yang
 * sama, dan lima teratas gampang jadi lima potongan adegan yang itu-itu juga — persis
 * keluhan yang baru saja ditutup.
 *
 * Poster sengaja tidak dipakai sama sekali: poster memuat judul, nama pemain, dan blok
 * kredit, dan seluruh desain ini berdiri di atas aturan sebaliknya — semua kata hidup di
 * HTML, nol di raster.
 */
const LANGKAH = 3;
const ambilSelang = (arr, n) => {
  const out = [];
  for (let i = 0; i < arr.length && out.length < n; i += LANGKAH) out.push(arr[i]);
  // Selangnya kehabisan sebelum kuota penuh: sisanya diambil berurutan dari yang belum
  // terpakai. Satu frame yang mirip masih lebih baik daripada satu slide tanpa foto.
  for (let i = 0; i < arr.length && out.length < n; i += 1) {
    if (!out.includes(arr[i])) out.push(arr[i]);
  }
  return out;
};

const still = $('Still film').first().json;
const backdrops = Array.isArray(still && still.backdrops) ? still.backdrops : [];
const dariTmdb = ambilSelang(
  backdrops.slice().sort((a, b) => (b.vote_average || 0) - (a.vote_average || 0)),
  slides.length
).map((b) => `https://image.tmdb.org/t/p/w1280${b.file_path}`);

// Disisipkan build.mjs: ekspresi asli kalau GOOGLE_AKTIF, `[]` kalau tidak. Node yang
// tidak dipasang tidak bisa dirujuk `$('...')` — ekspresinya melempar, bukan mengembalikan
// undefined. Pola yang sama dipakai untuk {{LOGO}}.
const dariGoogle = [];

const kolam = dariTmdb.length ? dariTmdb : dariGoogle;

/**
 * Slide yang menyebut seorang pemain memakai foto ORANGNYA, bukan still acak.
 *
 * Backdrop tidak membawa keterangan isinya, jadi still untuk slide "Sadie Sink sebagai
 * Jean Grey" bisa saja adegan Punisher — itu benar-benar keluar di render uji. TMDB
 * membawa nama asli DAN nama karakter tiap pemain, jadi teks slide bisa dicocokkan ke
 * dua-duanya. "Sadie Sink sebagai Jean Grey" kena lewat nama sekaligus karakter.
 *
 * Cuma 20 nama teratas: di bawah itu isinya pemeran figuran yang namanya justru bikin
 * cocok palsu. Minimal 4 huruf dan harus utuh sebagai kata — tanpa itu "MJ" dan "Ned"
 * kena di kata lain, dan yang tampil malah foto orang yang tidak dibahas.
 */
const cast = (($('Pemain film').first().json || {}).cast || [])
  .slice(0, 20)
  .flatMap((p) =>
    // Karakter TMDB sering ditulis "Frank Castle / Punisher" atau "Peter Parker /
    // Spider-Man". Dicocokkan utuh, tidak akan pernah kena — teks slide menyebut salah
    // satunya saja.
    [p.name, ...String(p.character || '').split('/')]
      .filter((n) => typeof n === 'string' && n.trim().length >= 4)
      .map((n) => ({ nama: n.trim(), foto: p.profile_path }))
  )
  .filter((x) => x.foto)
  // Nama terpanjang diperiksa duluan: "Jean Grey" harus menang atas "Jean" kalau
  // dua-duanya ada di daftar.
  .sort((a, b) => b.nama.length - a.nama.length);

const lolosRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const cariOrang = (teks) => {
  const t = String(teks || '');
  for (const c of cast) {
    if (new RegExp(`\\b${lolosRegex(c.nama)}\\b`, 'i').test(t)) return c.foto;
  }
  return null;
};

const CADANGAN = {
  konseptual: 'An abstract minimal still life suggesting an idea taking shape',
  tekstur: 'An extreme close-up of a raw material surface',
  dokumenter: 'A candid over-the-shoulder shot of someone working at a desk',
  tempat: 'A quiet architectural interior with strong directional light',
  properti: 'A single everyday object isolated on a plain surface',
};

return slides.map((s, i) => {
  const mode = CADANGAN[s.image_mode] ? s.image_mode : 'konseptual';
  const inti = String(s.image_prompt || '').trim() || CADANGAN[mode];
  // Slide 2+ diikat ke seri yang sama supaya carousel-nya tidak terbaca sebagai lima
  // gambar acak yang kebetulan bersebelahan. Yang diikat cuma cahaya dan warnanya —
  // dulu baris ini juga mengunci "same location", dan hasilnya lima frame yang nyaris
  // sama persis. Tiap slide punya teksnya sendiri, jadi adegannya harus ikut berbeda.
  const lanjutan = i === 0
    ? ''
    : ' Same visual series, same lighting and colour treatment as the other images in ' +
      'this set, but a clearly different scene, subject and camera angle.';

  // Slide 1 selalu foto artikel, jadi mencocokkan pemain di situ cuma membuang satu
  // nama dari kolam tanpa ada yang melihatnya.
  const orang = i === 0 ? null : cariOrang(`${s.heading || ''} ${s.body || ''}`);

  return {
    json: {
      code: brief.code,
      idx: i,
      total: slides.length,
      name: String(i + 1).padStart(2, '0'),
      heading: String(s.heading || '').trim(),
      body: String(s.body || '').trim(),
      image_prompt: `${c.image_series || ''} ${inti}.${lanjutan} ${SUFIKS}`.trim(),
      // Nilainya SAMA di kelima item. Gerbang `Ada foto asli?` dievaluasi per item, jadi
      // bendera yang berbeda antar item bakal membelah kelimanya ke dua cabang dan
      // menghancurkan pasangan indeks slide↔gambar.
      pakai_foto: kolam.length > 0,
      // Slide yang kehabisan kolam dapat null: node `Ambil foto` gagal untuk item itu,
      // dan slide-nya jatuh ke kartu berpola. Bukan foto slide lain.
      foto_url: orang ? `https://image.tmdb.org/t/p/w780${orang}` : kolam[i] || null,
      // Foto orang itu potret 2:3; dipasang di tengah, wajahnya kepotong. Titik fokusnya
      // dinaikkan supaya kepala tetap masuk frame. Still 16:9 tidak perlu digeser.
      foto_fokus: orang ? '50% 18%' : '50% 50%',
    },
  };
});

// Ubah binary jadi base64 yang benar-benar bisa dipakai di <img src="data:…">.
//
// Instance ini menyimpan binary di FILESYSTEM (N8N_DEFAULT_BINARY_DATA_MODE=filesystem),
// jadi `binary.data.data` berisi string literal "filesystem-v2" — bukan base64. Berkas
// aslinya ada di disk dan cuma bisa dibaca lewat helper. Dipasang apa adanya ke
// <img src="data:image/webp;base64,…">, yang keluar adalah ikon gambar rusak, di setiap
// slide, tanpa satu pun error di n8n dan dengan render-svc tetap membalas 200.
//
// Ditulis sebagai loop yang mengeluarkan SATU item per item masuk — termasuk yang tanpa
// binary. Node bawaan `Extract From File` tidak bisa dipakai di sini: dia MEMBUANG item
// tanpa binary alih-alih menandainya. Lima slide dengan dua gambar berhasil keluar
// sebagai dua item, dan pasangan per-indeks slide↔gambar hilang tanpa jejak; kalau
// semuanya gagal, keluarannya nol item dan seluruh cabang berhenti diam-diam sambil
// tetap dilaporkan "success".
const masuk = $input.all();
const keluar = [];

for (let i = 0; i < masuk.length; i++) {
  const b = masuk[i].binary && masuk[i].binary.data;
  keluar.push({
    json: {
      b64: b ? Buffer.from(await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64') : null,
      // Mime ikut dibawa, bukan diasumsikan: API menyajikan cover sebagai WebP, dan
      // menuliskannya sebagai image/jpeg bikin Chromium menolak merender gambarnya.
      mime: (b && b.mimeType) || null,
    },
  });
}

return keluar;

// Gabung N item slide jadi SATU item berisi slides[] HTML siap render.
//
// Node ini adalah titik masuk loop retry: `Render` yang gagal kembali ke sini, bukan
// ke `Gemini gambar`. Karena itu semua data dibaca lewat referensi node bernama,
// tidak lewat $input — saat dipanggil ulang, $input berisi keluaran node retry,
// bukan JPEG hasil konversi.
// Gambar juga sengaja tidak digenerate ulang: penyebab 422 adalah teks yang meluber,
// bukan gambarnya, dan regenerasi lima gambar tiap ronde itu bakar kuota percuma.
//
// Tiap ronde teksnya DIPERKECIL. Retry yang mengirim input identik ke render-svc
// deterministik akan gagal identik 8 kali — yang membuatnya konvergen adalah ini.
const ronde = $runIndex;
const brief = $('Siapkan brief').first().json;
const copy = $('Gemini copy').first().json.output;
const meta = $('Pecah slide').all().map((i) => i.json);
// Base64 dibaca dari `json.b64`, BUKAN dari `binary.data.data`.
//
// Instance ini menyimpan binary di filesystem, jadi `binary.data.data` berisi string
// literal "filesystem-v2" dan berkas aslinya cuma ditunjuk `binary.data.id`. Dipasang
// ke <img src="data:…;base64,filesystem-v2">, yang keluar ikon gambar rusak — di
// setiap slide, tanpa satu pun error. Node `Slide base64`/`Cover base64` yang membaca
// berkasnya dari disk. Yang masih boleh diambil dari `binary` cuma metadata seperti
// mimeType; nilainya utuh, yang jadi rujukan hanya `.data`.
const jpeg = $('Slide base64').all();

if (jpeg.length !== meta.length) {
  throw new Error(
    `Slide masuk ${jpeg.length} tapi metadata ${meta.length}. Pasangan per-indeks ` +
      'tidak bisa dipercaya — kemungkinan Gemini gambar men-drop item.'
  );
}

// Raster per slide. Slide yang gambarnya gagal tetap punya item di sini, isinya null —
// itu yang menjaga slide ke-4 tidak memakai gambar milik slide ke-1.
const raster = jpeg.map((it) => (it.json && it.json.b64) || null);
const adaRaster = raster.filter(Boolean);
// Nol gambar bukan kegagalan yang menahan pipeline: slide tanpa raster jatuh ke kartu
// warna, bukan ke gambar milik slide lain.
const gambarGagal = raster.filter((r) => !r).length;

// Gambar artikel, kalau ada. `Ambil cover` memakai onError:continueRegularOutput,
// jadi artikel tanpa gambar dan unduhan yang gagal sama-sama berakhir null di sini —
// dan dua-duanya memang ditangani sama: pakai gambar Gemini.
const unduhan = $('Cover base64').first().json || {};
const coverB64 = unduhan.b64 || null;
// Mime dibaca dari unduhan, bukan diasumsikan: API menyajikan cover sebagai WebP,
// dan menuliskannya sebagai image/jpeg bikin Chromium menolak merender gambarnya.
const coverMime = unduhan.mime || 'image/jpeg';

/**
 * SATU ATURAN: sebuah slide cuma boleh memakai gambarnya sendiri.
 *
 * Tidak ada slide yang meminjam gambar slide lain, dan foto artikel berhenti di slide 1.
 * Sebelumnya ada dua jalur pengulangan — slide gagal meminjam raster tetangga, lalu
 * kalau semua gagal kelimanya jatuh ke foto artikel dengan crop berbeda. Hasilnya satu
 * foto yang sama di lima slide, dan crop yang digeser tidak menyamarkan apa pun.
 *
 * Foto artikel tetap memegang slide 1 karena dia satu-satunya gambar yang benar-benar
 * menampilkan subjeknya: model gambar menolak menggambar karakter berhak cipta dan
 * wajah orang nyata, jadi "Spider-Man" atau "Sadie Sink" tidak akan pernah keluar dari
 * Gemini. Slide 2+ punya teksnya sendiri, jadi gambarnya dibuat dari teks itu.
 *
 * Slide tanpa gambar jatuh ke kartu berpola di bawah — bukan lubang, dan bukan foto
 * ulangan. Itu satu-satunya bentuk yang bikin lima slide mustahil terlihat sama.
 */
const latar = raster.map((b64, i) =>
  i === 0 && coverB64
    ? `data:${coverMime};base64,${coverB64}`
    : b64 ? `data:image/jpeg;base64,${b64}` : null
);

// Ronde 0 pakai ukuran penuh; tiap ronde berikutnya mengecil sampai lantai 70%.
// Digabung dengan pemangkasan kata di bawah, ronde 8 praktis mustahil meluber.
const skala = Math.max(0.7, 1 - ronde * 0.06);
const px = (n) => Math.round(n * skala);
const maksKata = (s, n) => {
  const kata = String(s == null ? '' : s).trim().split(/\s+/).filter(Boolean);
  return kata.length <= n ? kata.join(' ') : kata.slice(0, n).join(' ') + '…';
};

const esc = (s) =>
  String(s == null ? '' : s).replace(/[&<>"]/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])
  );

/**
 * Buang penekanan markdown.
 *
 * Model rutin menulis `*cameo*`, `*time skip*`, `**penting**`. Tidak satu pun tempat
 * tujuannya merender markdown: slide itu GAMBAR, dan caption Instagram/Facebook/LinkedIn
 * menampilkan teks apa adanya. Jadi yang terbaca justru bintangnya. Sudah terbit sekali
 * di render Spider-Man — tiga slide sekaligus.
 *
 * Garis bawah sengaja TIDAK ikut dibuang: `snake_case` itu hal biasa di artikel teknis,
 * dan merusaknya lebih mahal daripada membiarkan satu italic gaya `_begini_` lolos.
 */
const polos = (s) => String(s == null ? '' : s).replace(/\*+/g, '').replace(/`/g, '');

/**
 * Rapikan hashtag jadi bentuk yang benar-benar jadi tautan di Instagram.
 *
 * Prompt sudah meminta hashtag, tapi model rutin mengembalikan kata telanjang
 * ("spiderman marvel mcu") — dan caption yang terbit jadi deretan kata biasa yang
 * tidak bisa diklik dan tidak masuk pencarian mana pun. Sudah kejadian sekali.
 * Ditegakkan di kode, bukan diminta di prompt, sama seperti batas jumlahnya.
 *
 * Spasi di dalam satu tagar juga dibuang: "#brand new day" cuma jadi tagar "#brand",
 * dua kata sisanya hilang jadi teks biasa.
 */
const tagar = (daftar) =>
  (daftar || [])
    .map((t) => String(t == null ? '' : t).trim().replace(/^#+/, '').replace(/\s+/g, ''))
    .filter(Boolean)
    .slice(0, 5)
    .map((t) => `#${t}`)
    .join(' ');

// Disisipkan build.mjs dari icons/icon-192.png.
const LOGO = 'data:image/png;base64,';

// Satu-satunya ajakan yang muncul di gambar, dan isinya tetap tiap posting.
// Diarahkan ke bio, bukan URL: tautan di caption Instagram tidak bisa diklik dan
// praktis tidak ada yang mengetik ulang alamat dari sebuah gambar.
// Teks dari model untuk slide terakhir sengaja ditimpa — penutup tidak perlu
// berubah tiap artikel, dan membiarkan model menulisnya cuma menambah satu
// peluang gagal (menyelipkan URL sendiri, atau ajakan yang meleset).
const CTA_AKHIR = {
  heading: 'Artikel lengkapnya di link bio',
  body: 'Semua tulisan aku ada di sana — teknis, review film, sampai catatan keseharian.',
};

// ── warna aksen: dipilih model, TIDAK dipercaya ─────────────────────────────────
// Biru brand, dipakai kalau aksen dari model tidak lolos pemeriksaan.
const AKSEN_CADANGAN = '#5EC8FF';

/** Luminansi relatif WCAG. */
const luminansi = (hex) => {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
};
const kontras = (a, b) => {
  const [x, y] = [luminansi(a), luminansi(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};

/** Hue 0-360 dari hex. Dipakai untuk mengunci aksen di keluarga biru. */
const hue = (hex) => {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const maks = Math.max(r, g, b);
  const beda = maks - Math.min(r, g, b);
  if (!beda) return 0;
  const h =
    maks === r ? ((g - b) / beda) % 6 : maks === g ? (b - r) / beda + 2 : (r - g) / beda + 4;
  return (h * 60 + 360) % 360;
};

/**
 * Aksen diperiksa TIGA kali, dan tiap pemeriksaan menutup kegagalan yang berbeda:
 *
 * 1. Bentuk `#RRGGBB`. Model rutin mengembalikan bentuk yang tidak diminta — hashtag
 *    tanpa `#` baru saja membuktikannya.
 * 2. Kontras >= 4,5:1 terhadap putih. Aksen jadi LATAR chip berteks putih, jadi hex
 *    yang sah pun bisa tidak terbaca; pastel lolos pemeriksaan bentuk tapi gagal ini.
 * 3. Hue 180-265 (teal sampai indigo). Ini yang menjaga identitas brand: foto dan
 *    layout boleh beda tiap artikel, warnanya tetap satu keluarga supaya orang tahu
 *    itu postingan yang sama tanpa membaca nama.
 *
 * Gagal salah satu berarti jatuh ke biru brand — bukan terbit dengan chip yang tidak
 * terbaca atau warna yang tidak ada hubungannya dengan brand.
 */
const aksen = (() => {
  const v = String(copy.accent == null ? '' : copy.accent).trim();
  if (!/^#[0-9a-fA-F]{6}$/.test(v)) return AKSEN_CADANGAN;
  if (kontras(v, '#FFFFFF') < 4.5) return AKSEN_CADANGAN;
  const h = hue(v);
  return h >= 180 && h <= 265 ? v.toUpperCase() : AKSEN_CADANGAN;
})();

// ── layout: dipilih model dari daftar tertutup ──────────────────────────────────
// Tertutup, bukan bebas, karena tiap bentuk harus bisa dibuktikan tidak meluber.
const LAYOUT = ['blok-bawah', 'pias-bawah', 'tengah'];
/*
 * Still film DIPAKSA ke `pias-bawah`, apa pun yang dipilih model.
 *
 * Backdrop TMDB semuanya 16:9; kanvas slide 4:5. Di `blok-bawah` dan `tengah` foto mengisi
 * 1080x1350, jadi `object-fit: cover` membuang 55% lebarnya dan subjeknya gampang
 * kepotong keluar frame — merusak satu-satunya alasan memakai foto asli. `pias-bawah`
 * memberi foto area 1080x783 dan cuma membuang 22%.
 *
 * Artikel non-film tetap bebas memilih ketiganya: gambar Gemini digenerate langsung di
 * rasio kanvas, jadi tidak ada yang dibuang.
 */
const adaFotoAsli = meta.some((m) => m.pakai_foto);
const layout = adaFotoAsli
  ? 'pias-bawah'
  : LAYOUT.includes(copy.layout) ? copy.layout : LAYOUT[0];

/**
 * Foto tampil UTUH — opacity 1, dan tidak ada satu pun lapisan yang menutup seluruh
 * kanvas. Versi sebelumnya memasang foto di opacity .42 lalu menimpanya dengan veil
 * .62–.96 sekanvas; yang sampai ke mata tinggal 16% di ujung atas dan 1,7% di bawah,
 * jadi review film dan catatan teknis menghasilkan kotak hitam yang sama persis.
 *
 * Kontras sekarang dijaga LOKAL: hanya di belakang teks, lewat blok/panel/scrim
 * sesuai layout. Itu yang membuat foto tetap terbaca sekaligus teks tetap aman di
 * atas foto seterang apa pun.
 *
 * `.fotolayer` memotong lapisan foto, dan itu WAJIB: transform:scale tidak mengubah
 * layout tapi tetap menambah scrollable overflow, jadi zoom 1.12 pada foto setinggi
 * kanvas membuat render-svc mengukur 1431px dan membalas 422 overflow — di SETIAP
 * artikel, dan tidak pernah sembuh oleh loop penyusutan karena penyebabnya bukan teks.
 * Yang dipotong hanya lapisan fotonya; lapisan teks justru harus tetap boleh meluber
 * supaya aturan 11 masih bisa menangkap teks yang benar-benar kepanjangan.
 */
const CSS = `
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:1080px;height:1350px;overflow:hidden}
body{font-family:'Inter',system-ui,-apple-system,sans-serif;background:#0B0F14;color:#F5F7FA;position:relative}
/* Pembungkus foto memotong dirinya sendiri — lihat catatan di atas blok CSS. */
.fotolayer{position:absolute;inset:0;overflow:hidden}
.bg{position:absolute;inset:0;width:1080px;height:1350px;object-fit:cover}
/* Tanpa gambar: kartu aksen, bukan kanvas kosong dan bukan foto slide lain.
   EMPAT pola, dipilih dari nomor slide. Satu gradien yang sama di empat slide cuma
   memindahkan keluhan "gambarnya sama semua" dari foto ke latar belakang. */
.kartu{position:absolute;inset:0;background:#0B0F14}
.k0{background:linear-gradient(155deg,${aksen} 0%,#0B0F14 72%)}
.k1{background:radial-gradient(88% 68% at 82% 16%,${aksen} 0%,#0B0F14 66%)}
.k2{background:linear-gradient(200deg,#0B0F14 34%,${aksen} 100%)}
.k3{background:repeating-linear-gradient(45deg,${aksen}66 0 ${px(4)}px,rgba(0,0,0,0) ${px(4)}px ${px(30)}px),linear-gradient(160deg,#131A22 0%,#0B0F14 100%)}
/* Redup tipis sekanvas, cuma untuk menahan foto yang benar-benar putih. .22 masih
   menyisakan 78% foto — bandingkan dengan veil lama yang menyisakan 4–16%. */
.redup{position:absolute;inset:0;background:rgba(11,15,20,.22)}
.wrap{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:space-between;padding:${px(72)}px ${px(64)}px}
/* Kepala duduk langsung di atas foto, jadi dia bawa scrim sendiri. */
.atas{display:flex;justify-content:space-between;align-items:center;font-size:${px(24)}px;font-weight:700;letter-spacing:.16em;text-transform:uppercase}
.merek{display:flex;align-items:center;gap:${px(16)}px;background:rgba(11,15,20,.72);padding:${px(12)}px ${px(22)}px ${px(12)}px ${px(12)}px;border-radius:999px}
.logo{height:${px(46)}px;width:auto;display:block;flex:none}
.nomor{background:rgba(11,15,20,.72);padding:${px(12)}px ${px(20)}px;border-radius:999px;color:#C3CCD6;letter-spacing:.1em}
/* Zona teks. Sengaja TANPA overflow:hidden — teks yang meluber harus menambah
   scrollHeight supaya render-svc bisa membalas 422 aturan 11 dan loop ronde
   memperkecilnya. Ditutup di sini berarti teks terpotong diam-diam. */
.teks{padding:${px(48)}px ${px(44)}px}
.kicker{display:inline-block;background:${aksen};color:#fff;font-size:${px(23)}px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;padding:${px(10)}px ${px(20)}px;border-radius:${px(6)}px;margin-bottom:${px(22)}px}
h1{font-size:${px(74)}px;line-height:1.08;font-weight:800;letter-spacing:-.02em;text-transform:uppercase}
h1.cta{font-size:${px(58)}px;text-transform:none}
p{font-size:${px(34)}px;line-height:1.42;color:#D7DEE6;margin-top:${px(22)}px}
/* blok-bawah: pola HEROID — foto utuh, teks di dalam blok pekat di bawah. */
.l-blok .wrap{justify-content:space-between}
.l-blok .teks{background:rgba(9,12,16,.9);border-radius:${px(20)}px;border-left:${px(10)}px solid ${aksen}}
/* pias-bawah: foto 58% atas, panel warna solid 42% bawah. */
.l-pias .bg{height:783px;bottom:auto}
.l-pias .kartu{height:783px;bottom:auto}
.l-pias .redup{height:783px;bottom:auto}
.l-pias body,.l-pias{background:#0B0F14}
.l-pias .teks{background:#0B0F14;border-top:${px(8)}px solid ${aksen};border-radius:0;padding-top:${px(40)}px}
/* tengah: judul di tengah, scrim gradien terbatas di zona teksnya saja. */
/* tengah: scrim harus BENAR-BENAR sampai transparan sebelum tepi kotaknya, kalau
   tidak yang terlihat kotak abu-abu bersudut, bukan bayangan lembut. Karena itu
   berhenti di 72% dengan padding lega — sisa 28% kotak murni transparan.
   Konsekuensinya bagian pinggir teks kehilangan sebagian kontras, jadi ditambal
   text-shadow: dua lapis pelindung, dan yang kedua tidak bergantung ukuran kotak. */
.l-tengah .wrap{justify-content:space-between}
.l-tengah .tengahkan{flex:1;display:flex;align-items:center}
.l-tengah .teks{background:radial-gradient(72% 54% at 50% 50%,rgba(9,12,16,.93) 0%,rgba(9,12,16,.74) 46%,rgba(9,12,16,0) 72%);text-align:center;padding:${px(104)}px ${px(72)}px}
.l-tengah .kicker{margin-left:auto;margin-right:auto}
.l-tengah h1,.l-tengah p{text-shadow:0 ${px(2)}px ${px(20)}px rgba(0,0,0,.9)}
`.trim();

/**
 * Chip kategori — tempat warna aksen hidup, dan satu-satunya bagian yang menyebut
 * topik artikel. Diambil dari tag pertama, bukan dari field baru ke model: tag-nya
 * sudah ada di brief, sudah ditulis manusia, dan tidak bisa mengarang.
 */
const KICKER = (() => {
  const t = String(brief.tags || '').split(',')[0].trim();
  return (t || 'Artikel').slice(0, 18);
})();

const KELAS = { 'blok-bawah': 'l-blok', 'pias-bawah': 'l-pias', tengah: 'l-tengah' };

const slides = meta.map((m, i) => {
  const akhir = i === meta.length - 1;
  // Slide terakhir memakai teks tetap; apa pun yang ditulis model untuk slide itu dibuang.
  const sumber = akhir ? CTA_AKHIR : m;

  const heading = maksKata(polos(sumber.heading), Math.max(5, 8 - Math.floor(ronde / 2)));
  const body = maksKata(polos(sumber.body), Math.max(10, 25 - ronde * 2));

  const teks =
    `<div class="teks">` +
    `<span class="kicker">${esc(akhir ? 'Baca selengkapnya' : KICKER)}</span>` +
    `<h1${akhir ? ' class="cta"' : ''}>${esc(heading)}</h1>` +
    `${body ? `<p>${esc(body)}</p>` : ''}` +
    `</div>`;

  return `<!doctype html>
<html lang="id" class="${KELAS[layout]}"><head><meta charset="utf-8"><style>${CSS}</style></head><body>
${latar[i]
      // Foto artikel di slide 1 diturunkan sedikit titik fokusnya: subjek foto banner
      // hampir selalu duduk di atas tengah, dan blok teks memakan sepertiga bawah.
      ? `<div class="fotolayer"><img class="bg" style="object-position:${i === 0 && coverB64 ? '50% 30%' : m.foto_fokus || '50% 50%'}" src="${latar[i]}"></div>`
      : `<div class="kartu k${i % 4}"></div>`}
${latar[i] ? '<div class="redup"></div>' : ''}
<div class="wrap">
  <div class="atas">
    <span class="merek"><img class="logo" src="${LOGO}" alt="">Daffathan Labs</span>
    <span class="nomor">${i + 1} / ${meta.length}</span>
  </div>
  ${layout === 'tengah' ? `<div class="tengahkan">${teks}</div>` : teks}
</div>
</body></html>`;
});

// Artikel tanpa gambar: latar Gemini slide 1 dipromosikan jadi gambar artikel.
// Dirender lanskap 1200x630 — satu ukuran yang melayani og:image dan gambar tunggal
// LinkedIn sekaligus. Nol teks, nol logo: ini gambar artikel, bukan slide.
// Kalau artikel sudah punya cover, `hero` tetap null dan tidak ada yang di-commit.
const hero = coverB64 || !adaRaster[0]
  ? null
  : `<!doctype html>
<html><head><meta charset="utf-8"><style>
*{margin:0;padding:0}html,body{width:1200px;height:630px;overflow:hidden;background:#0B0F14}
img{width:1200px;height:630px;object-fit:cover;display:block}
</style></head><body><img src="data:image/jpeg;base64,${adaRaster[0]}"></body></html>`;

return [{
  json: {
    code: brief.code,
    folder: brief.folder,
    url_id: brief.url_id,
    url_en: brief.url_en,
    dilewat: brief.dilewat,
    gambar_gagal: gambarGagal,
    ronde: ronde + 1,
    hero,
    // Diteruskan supaya cabang commit balik tidak perlu membaca `Siapkan brief` lagi.
    repo: brief.repo,
    berkas_md: brief.berkas_md,
    linkedin_caption: polos(copy.linkedin_caption),
    // Dipotong keras di kode, bukan cuma diminta di prompt: model rutin melewati
    // batas yang hanya disebut dalam instruksi.
    ig_caption: [polos(copy.ig_caption), tagar(copy.hashtags)].filter(Boolean).join('\n\n'),
    // Tanpa hashtag: di Facebook hashtag tidak menambah jangkauan, cuma bikin
    // tulisannya terlihat seperti hasil bot.
    fb_caption: polos(copy.fb_caption),
    slides,
  },
}];

// Gerbang cabang commit balik. Mengembalikan [] kalau tidak ada yang perlu di-commit —
// dan nol item berarti seluruh rantai di bawahnya tidak dieksekusi sama sekali, jadi
// tidak perlu node IF terpisah. Pola yang sama dipakai `siapkan-brief.js`.
//
// Yang memicu: artikel tidak punya gambar sama sekali, sehingga `Rakit slide`
// mempromosikan latar Gemini slide 1 jadi hero. Artikel yang sudah punya cover
// menghasilkan hero null dan berhenti di sini.
//
// Dibaca lewat referensi node, bukan $input: masukan node ini adalah balasan
// render-svc (`{urls, previewUrl}`), bukan keluaran `Rakit slide`.
const b = $('Rakit slide').first().json;
const urls = $('Render').first().json.urls || [];

if (!b.hero) return [];

// URL hero di render-svc, sumber byte yang akan di-commit. Dicari berdasarkan nama
// berkasnya, bukan indeks: `urls` juga memuat 5 slide dan urutannya bisa berubah.
const sumber = urls.find((u) => u.includes('/hero.jpg'));
if (!sumber) {
  throw new Error(
    `hero disusun tapi tidak ada di balasan render-svc. urls = ${JSON.stringify(urls).slice(0, 300)}`
  );
}

const repo = String(b.repo || '').trim();
const folder = String(b.folder || '').trim();
const berkas = (b.berkas_md || []).filter((n) => typeof n === 'string' && n.endsWith('.md'));

// Gagal keras, bukan diam: kalau salah satu tidak masuk akal, PUT-nya akan menulis ke
// path yang salah di repo publik. Lebih baik cabang ini mati daripada mengarang path.
if (!/^[\w.-]+\/[\w.-]+$/.test(repo)) {
  throw new Error(`repo tidak berbentuk owner/nama: ${JSON.stringify(repo)}`);
}
if (!/^[\w.-]+$/.test(folder)) {
  throw new Error(`folder artikel tidak aman untuk path: ${JSON.stringify(folder)}`);
}
if (!berkas.length) {
  throw new Error('berkas_md kosong — publish.js tidak mengirim md_files untuk folder ini.');
}

// Cabang `main` dikunci karena Action-nya sendiri hanya jalan di main
// (.github/workflows/publish-articles.yml: `if: github.ref == 'refs/heads/main'`).
return [{
  json: {
    repo,
    folder,
    berkas,
    sumber,
    path_gambar: `articles/${folder}/hero.jpg`,
    url_gambar: `https://raw.githubusercontent.com/${repo}/main/articles/${folder}/hero.jpg`,
    judul: b.folder,
  },
}];

// Fan-out satu item per berkas .md, supaya `Ambil md` melakukan satu GET per berkas.
// Dijalankan SETELAH gambarnya tersimpan: markdown tidak boleh menunjuk URL yang
// masih 404, karena kalau full sync kebetulan jalan di jendela itu,
// `convertSingleImage` gagal dan `image` artikelnya jadi null lagi.
const rencana = $('Susun commit').first().json;
const simpan = $input.first().json;

// Balasan sukses PUT /contents memuat objek `content`. Node HTTP-nya memakai
// onError:continueRegularOutput supaya kegagalan tetap sampai ke e-mail, jadi
// pemeriksaannya harus di sini — bukan diserahkan ke status HTTP.
const sudahAda = simpan && simpan.message && /already exists/i.test(simpan.message);
if (!(simpan && simpan.content && simpan.content.sha) && !sudahAda) {
  throw new Error(
    `hero.jpg gagal di-commit, markdown tidak disentuh: ${JSON.stringify(simpan).slice(0, 300)}`
  );
}

return rencana.berkas.map((nama) => ({
  json: {
    nama,
    path: `articles/${rencana.folder}/${nama}`,
    url_gambar: rencana.url_gambar,
    repo: rencana.repo,
  },
}));

// Sisipkan gambar ke markdown: satu baris metadata dan satu <img> di isi.
//
// Dua-duanya perlu, dan gunanya beda. `<!-- image: -->` jadi thumbnail kartu dan
// og:image. `<img>` di isi jadi gambar besar di halaman detail — halaman itu merender
// `content`, jadi tanpa <img> tidak ada gambar yang terlihat saat artikel dibuka.
//
// Selain dua baris itu, berkasnya tidak boleh berubah sedikit pun. Ini menulis ke repo
// tulisan orang; diff yang mengandung perubahan lain adalah bug, bukan kerapian.

/** Sisip satu baris SETELAH baris pertama yang cocok, tanpa menyentuh yang lain. */
const sisipSetelah = (baris, cocok, isi) => {
  const i = baris.findIndex(cocok);
  if (i < 0) return null;
  return [...baris.slice(0, i + 1), isi, ...baris.slice(i + 1)];
};

const esc = (s) =>
  String(s == null ? '' : s).replace(/[&<>"]/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])
  );

const keluar = [];

for (const item of $input.all()) {
  const g = item.json;
  const rencana = $('Pecah md').all().find((x) => x.json.path === g.path);
  if (!rencana) throw new Error(`tidak ketemu rencana untuk ${g.path}`);
  const url = rencana.json.url_gambar;

  if (typeof g.content !== 'string' || !g.sha) {
    throw new Error(
      `balasan GET /contents tidak lengkap untuk ${g.path}: ${JSON.stringify(g).slice(0, 200)}`
    );
  }

  // GitHub mengembalikan base64 ber-baris-baru; atob/Buffer sama-sama tidak masalah,
  // tapi barisnya harus dibuang dulu di sebagian runtime.
  const asli = Buffer.from(String(g.content).replace(/\s/g, ''), 'base64').toString('utf8');

  // Sudah punya gambar berarti ada yang menambahkannya di antara publish dan sekarang.
  // Menimpanya berarti membuang gambar pilihan manusia demi gambar mesin.
  if (/<!--\s*image:\s*\S/i.test(asli)) {
    keluar.push({ json: { path: g.path, lewati: true, alasan: 'sudah punya <!-- image: -->' } });
    continue;
  }

  const baris = asli.split('\n');
  const judul = (/<!--\s*title:\s*(.*?)\s*-->/i.exec(asli) || [])[1] || 'Gambar artikel';

  // 1) baris metadata. Ditaruh setelah `excerpt` supaya urutannya sama dengan 45
  //    artikel yang sudah ada; kalau tidak ada excerpt, setelah komentar terakhir.
  let hasil =
    sisipSetelah(baris, (b) => /^<!--\s*excerpt:/i.test(b), `<!-- image: ${url} -->`) ||
    sisipSetelah(baris, (b) => /^<!--[\s\S]*-->\s*$/.test(b), `<!-- image: ${url} -->`);
  if (!hasil) throw new Error(`${g.path}: tidak ada blok metadata <!-- ... --> di atas berkas`);

  // 2) <img> di isi, setelah judul H1 — persis pola 45 artikel yang sudah ada.
  //    Kalau tidak ada H1, ditaruh sebelum paragraf pertama.
  const img = `<img width="800" alt="${esc(judul)}" src="${url}" />`;
  const iJudul = hasil.findIndex((b) => /^#\s+\S/.test(b));
  if (iJudul >= 0) {
    // Deretan baris kosong setelah judul diganti pola baku `kosong, img, kosong`,
    // bukan disisipi. Menyisipi bikin artikel yang sudah punya baris kosong di situ
    // berakhir dengan dua baris kosong berturut-turut — jejak yang tidak perlu ada
    // di diff artikel orang.
    let j = iJudul + 1;
    while (j < hasil.length && hasil[j].trim() === '') j++;
    hasil = [...hasil.slice(0, iJudul + 1), '', img, '', ...hasil.slice(j)];
  } else {
    const i = hasil.findIndex((b) => b.trim() && !/^<!--/.test(b));
    if (i < 0) throw new Error(`${g.path}: tidak ada isi setelah blok metadata`);
    hasil = [...hasil.slice(0, i), img, '', ...hasil.slice(i)];
  }

  keluar.push({
    json: {
      path: g.path,
      sha: g.sha,
      lewati: false,
      isi_b64: Buffer.from(hasil.join('\n'), 'utf8').toString('base64'),
    },
  });
}

return keluar;

// Satu item per URL slide, untuk membuat item container IG satu per satu.
// render-svc mengembalikan urls[] urut sesuai images[] yang dikirim, jadi urutan
// carousel-nya mengikuti urutan slide.
//
// Dibaca dari node `Render`, BUKAN dari $input: node ini berjalan setelah `Tunggu
// approval`, jadi $input berisi data request webhook resume (query/body/headers),
// bukan hasil render.
const hasil = $('Render').first().json;

// hero.jpg menumpang panggilan Render yang sama, tapi dia gambar artikel 1200x630 —
// bukan slide. Tanpa saringan ini dia jadi slide terakhir carousel: lanskap, di-crop
// jadi potret, dan tidak pernah diminta siapa pun.
const urls = (hasil.urls || []).filter((u) => !u.includes('/hero.jpg'));

if (!urls.length) {
  throw new Error(`render-svc tidak mengembalikan urls[]: ${JSON.stringify(hasil).slice(0, 300)}`);
}
return urls.map((url, i) => ({ json: { url, idx: i } }));

// Kumpulkan id container anak jadi satu daftar untuk container CAROUSEL.
// Node IG memakai onError:continueRegularOutput supaya satu slide gagal tidak
// mematikan eksekusi — tapi carousel dengan slide bolong jangan diterbitkan.
const items = $input.all();
const ids = items.map((i) => i.json && i.json.id).filter(Boolean);

if (ids.length !== items.length) {
  const gagal = items.filter((i) => !(i.json && i.json.id));
  throw new Error(
    `${ids.length}/${items.length} item container IG berhasil. Contoh error: ` +
      JSON.stringify(gagal[0] && gagal[0].json).slice(0, 400)
  );
}
if (ids.length < 2) throw new Error(`Carousel IG butuh minimal 2 anak, dapat ${ids.length}.`);

return [{ json: { children: ids.join(','), jumlah: ids.length } }];

// Kumpulkan id foto hasil unggah unpublished jadi satu body post feed.
//
// Facebook tidak punya endpoint carousel. Pola resminya dua langkah: tiap foto
// diunggah dengan published=false (tercipta, tapi tidak tayang sendiri-sendiri),
// lalu SATU post feed melampirkan semuanya lewat attached_media[n].
//
// Sama seperti carousel IG: node FB memakai onError:continueRegularOutput supaya
// satu foto gagal tidak mematikan eksekusi — tapi post dengan lampiran bolong
// jangan diterbitkan. Lebih baik gagal keras di sini daripada tayang cacat.
const items = $input.all();
const ids = items.map((i) => i.json && i.json.id).filter(Boolean);

if (ids.length !== items.length) {
  const gagal = items.filter((i) => !(i.json && i.json.id));
  throw new Error(
    `${ids.length}/${items.length} foto FB berhasil diunggah. Contoh error: ` +
      JSON.stringify(gagal[0] && gagal[0].json).slice(0, 400)
  );
}
if (ids.length < 2) throw new Error(`Post FB butuh minimal 2 foto, dapat ${ids.length}.`);

// Bentuk kunci ber-indeks `attached_media[0]` adalah bentuk yang didokumentasikan
// Meta, dan nilainya JSON string — bukan objek. Dikirim form-urlencoded, jadi tiap
// kunci berdiri sendiri. Urutan lampiran mengikuti urutan slide.
const body = {};
ids.forEach((id, i) => {
  body[`attached_media[${i}]`] = JSON.stringify({ media_fbid: String(id) });
});

return [{ json: { body, jumlah: ids.length } }];
